implementation:
size_t RegisterJPEGImage() {
    MagickInfo *magick_info;
    const char *description = "JPEG image format";
    const char *version = MagickLibVersionText;

    magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
    if (magick_info == (MagickInfo *) NULL)
        return 0;

    (void) memset(magick_info, 0, sizeof(MagickInfo));
    magick_info->name = (char *) AcquireQuantumMemory(5, sizeof(char));
    if (magick_info->name == (char *) NULL)
    {
        RelinquishMagickMemory(magick_info);
        return 0;
    }

    (void) memcpy(magick_info->name, "JPEG", 5);
    magick_info->description = (char *) strdup(description);
    magick_info->decoder = JPEGReadImage;
    magick_info->encoder = JPEGWriteImage;
    magick_info->thread_support = MagickTrue;

    if (strcmp(version, "6.9.0") < 0)
        magick_info->thread_support = MagickFalse;

    magick_info->mime_type = (char *) strdup("image/jpeg");

    if (!RegisterMagickInfo(magick_info))
    {
        RelinquishMagickMemory(magick_info->name);
        RelinquishMagickMemory(magick_info->description);
        RelinquishMagickMemory(magick_info->mime_type);
        RelinquishMagickMemory(magick_info);
        return 0;
    }

    return sizeof(MagickInfo);
}
